/* AppAdminApprovalMapper.backfillReqNodeCd */
UPDATE TB_USER_ATTD_REQ
   SET NODE_CD     = #{nodeCd}
     , UPDATE_NO   = #{updateNo}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND REQ_ID   = #{reqId}
   AND NODE_CD IS NULL
   AND DEL_YN   = 'N'
